const langs = ['pt', 'es', 'en', 'fr'];

const tags = {
  'Balcão': 14,
  'Cafeteria': 16,
  "Child's bedroom": 20,
  'Cozinha': 1,
  'Detalhes': 10,
  'Exterior': 9,
  'Fachada': 2,
  'Garagem': 8,
  'Jardim': 5,
  'Outros': 11,
  'Piscina': 6,
  'Plano': 18,
  'Quarto de banho': 4,
  'Quarto': 3,
  'Receção': 13,
  'Resort': 19,
  'Sala de estar': 12,
  'Sala de jantar': 15,
  'Terraço': 7,
  'Visualizações': 17
};

const nonempty = x =>
  typeof x === 'string' && x.trim().length > 0;

const id = x =>
  String(x || '').replace(/-/g, '').toLowerCase();

// CORRIGIDO: Aceita URLs das fotos independentemente
// da língua usada no site MTPHomes.
// Exemplos:
// /aluguer/fotos/3/...
// /en/rentals/fotos/3/...
// /es/.../fotos/3/...
// /fr/.../fotos/3/...

const regexFoto =
  /^https:\/\/www\.mtphomes\.pt\/(?:[^/?#]+\/){1,2}fotos\/3\//i;

function validate(d, page) {

  if (
    !d ||
    !['PARCIAL', 'PENDENTE', 'VALIDADO'].includes(d.estado) ||
    id(d.pageId) !== id(page)
  ) {
    throw Error('BLOQUEADO: estado ou pageId divergente.');
  }

  if (
    !nonempty(d.alojamento) ||
    !nonempty(d.urlAnuncio) ||
    !Number.isInteger(d.totalFotos) ||
    d.totalFotos < 1 ||
    !Array.isArray(d.fotos) ||
    !Array.isArray(d.pendentes)
  ) {
    throw Error('BLOQUEADO: estrutura incompleta.');
  }

  const all = [...d.fotos, ...d.pendentes];

  if (
    all.length !== d.totalFotos ||
    new Set(all.map(f => f.numero)).size !== d.totalFotos ||
    new Set(all.map(f => f.url)).size !== d.totalFotos
  ) {
    throw Error('BLOQUEADO: contagem ou fotos duplicadas.');
  }

  // Validação de números e URLs multilíngues
  for (const f of all) {
    if (
      !Number.isInteger(f.numero) ||
      f.numero < 1 ||
      f.numero > d.totalFotos ||
      typeof f.url !== 'string' ||
      !regexFoto.test(f.url)
    ) {
      throw Error(
        'BLOQUEADO: numero ou URL de foto invalido.'
      );
    }
  }

  // Validar fotografias já concluídas
  for (const f of d.fotos) {

    if (
      f.sucesso !== true ||
      !nonempty(f.nome) ||
      f.acessibilidade !== false ||
      !Number.isInteger(f.etiqueta?.id) ||
      tags[f.etiqueta?.nome] !== f.etiqueta?.id
    ) {
      throw Error('BLOQUEADO: foto concluida invalida.');
    }

    for (const l of langs) {
      for (const k of ['title', 'descricao', 'alt']) {

        if (
          !nonempty(f.traducoes?.[l]?.[k]) ||
          (k === 'title' && f.traducoes[l][k].length > 70) ||
          (k === 'alt' && f.traducoes[l][k].length > 125)
        ) {
          throw Error(
            'BLOQUEADO: traducao concluida incompleta.'
          );
        }
      }
    }
  }

  if (
    d.fotosProcessadas !== undefined &&
    d.fotosProcessadas !== d.fotos.length
  ) {
    throw Error(
      'BLOQUEADO: fotosProcessadas inconsistente.'
    );
  }

  if (
    d.estado === 'VALIDADO' &&
    d.pendentes.length
  ) {
    throw Error(
      'BLOQUEADO: VALIDADO com pendentes.'
    );
  }

  const min = d.pendentes.length
    ? Math.min(...d.pendentes.map(f => f.numero))
    : null;

  if (
    d.proximaFoto !== undefined &&
    d.proximaFoto !== min
  ) {
    throw Error(
      'BLOQUEADO: proximaFoto inconsistente.'
    );
  }

  return d;
}

function payload(d) {

  const text = JSON.stringify(d, null, 2);
  const parts = [];

  let part = '';

  for (const ch of text) {
    if (part.length + ch.length > 1900) {
      parts.push(part);
      part = '';
    }
    part += ch;
  }

  if (part) parts.push(part);

  if (parts.length > 100) {
    throw Error(
      'BLOQUEADO: JSON excede capacidade do bloco Notion.'
    );
  }

  return {
    code: {
      language: 'json',
      rich_text: parts.map(content => ({
        type: 'text',
        text: { content }
      }))
    }
  };
}

// Selecionar alojamentos válidos
const validos = [];
const ignorados = [];

for (const [i, item] of $input.all().entries()) {

  let pageId = '';
  let nome = '';

  try {

    const p = $('Notion - Incompletos')
      .itemMatching(i).json;

    pageId = p.id;

    nome = Object.values(p.properties || {})
      .find(v => v.type === 'title')
      ?.title?.map(t =>
        t.plain_text ?? t.text?.content ?? ''
      ).join('') || pageId;

    const r = item.json;

    if (!Array.isArray(r.results) || r.has_more) {
      throw Error('Leitura de blocos incompleta.');
    }

    const found = [];

    for (const b of r.results) {

      if (b.type !== 'code') continue;

      const text = (b.code.rich_text || [])
        .map(t =>
          t.plain_text ?? t.text?.content ?? ''
        ).join('');

      let d;

      try {
        d = JSON.parse(text);
      } catch {
        if (/"estado"\s*:/.test(text)) {
          throw Error(
            'Bloco de fotos com JSON ilegivel.'
          );
        }
        continue;
      }

      if (
        d &&
        typeof d === 'object' &&
        ('estado' in d || 'fotos' in d)
      ) {

        d.pendentes ??=
          d.estado === 'VALIDADO' ? [] : undefined;

        validate(d, pageId);

        found.push({
          data: d,
          blockId: b.id,
          snapshot: text,
          pageId
        });
      }
    }

    if (found.length !== 1) {
      throw Error(
        'Encontrados ' + found.length +
        ' JSONs de fotos; necessario exatamente 1.'
      );
    }

    payload(found[0].data);

    if (found[0].data.pendentes.length === 0) {
      throw Error(
        'Sem fotos pendentes; rever status manualmente.'
      );
    }

    validos.push(found[0]);

  } catch (e) {
    ignorados.push({
      pageId,
      nome,
      motivo: e.message
    });
  }
}

// Não aceitar páginas repetidas nem imagens
// partilhadas entre candidatos

const owners = new Map();
const pages = new Set();
const blocked = new Set();

for (const s of validos) {

  if (pages.has(id(s.pageId))) {
    blocked.add(s.pageId);
  }

  pages.add(id(s.pageId));

  for (const f of [
    ...s.data.fotos,
    ...s.data.pendentes
  ]) {

    if (
      owners.has(f.url) &&
      owners.get(f.url) !== s.pageId
    ) {
      blocked.add(s.pageId);
      blocked.add(owners.get(f.url));
    }

    owners.set(f.url, s.pageId);
  }
}

const fila = validos.filter(s => {

  if (!blocked.has(s.pageId)) return true;

  ignorados.push({
    pageId: s.pageId,
    nome: s.data.alojamento,
    motivo:
      'Pagina duplicada ou URL partilhado entre alojamentos.'
  });

  return false;
});

// Prioridade: menor quantidade de fotos pendentes
fila.sort((a, b) =>
  a.data.pendentes.length -
  b.data.pendentes.length ||
  a.data.alojamento.localeCompare(b.data.alojamento)
);

const resumo = {
  candidatosValidos: fila.length,
  ignorados,
  ordem: fila.map(s => ({
    pageId: s.pageId,
    nome: s.data.alojamento,
    pendentes: s.data.pendentes.length
  }))
};

if (!fila.length) {
  return [{
    json: {
      selecionado: false,
      resumo,
      mensagem:
        'Nenhum alojamento valido com fotos pendentes. Consultar resumo.ignorados.'
    }
  }];
}

return [{
  json: {
    ...fila[0],
    selecionado: true,
    resumo
  }
}];


/**
 * ============================================================
 * MTPHOMES | PREPARAR FOTOGRAFIA PARA ANÁLISE IA
 * ============================================================
 *
 * Objetivo:
 *  1. Validar o progresso guardado no Notion.
 *  2. Identificar a próxima fotografia pendente.
 *  3. Preparar o prompt multilíngue.
 *  4. Construir o pedido para a API Groq.
 *
 * Idiomas: PT, ES, EN, FR
 * Modelo: qwen/qwen3.8-27b
 *
 * Segurança:
 *  - Não altera fotografias já processadas.
 *  - Não aceita fotografias duplicadas.
 *  - Valida o conteúdo das traduções existentes.
 *  - Aceita URLs MTPHomes em diferentes idiomas.
 * ============================================================
 */


// ============================================================
// 1. CONFIGURAÇÕES
// ============================================================

const IDIOMAS = ['pt', 'es', 'en', 'fr'];

const ETIQUETAS = {
  'Balcão': 14,
  'Cafeteria': 16,
  "Child's bedroom": 20,
  'Cozinha': 1,
  'Detalhes': 10,
  'Exterior': 9,
  'Fachada': 2,
  'Garagem': 8,
  'Jardim': 5,
  'Outros': 11,
  'Piscina': 6,
  'Plano': 18,
  'Quarto de banho': 4,
  'Quarto': 3,
  'Receção': 13,
  'Resort': 19,
  'Sala de estar': 12,
  'Sala de jantar': 15,
  'Terraço': 7,
  'Visualizações': 17
};

const CONFIG_GROQ = {
  model: 'qwen/qwen3.8-27b',
  temperature: 0.2,
  max_completion_tokens: 1500
};

// Aceita, por exemplo:
// /aluguer/fotos/3/...
// /en/rentals/fotos/3/...
// Outros caminhos de idioma com a mesma estrutura.

const REGEX_FOTO =
  /^https:\/\/www\.mtphomes\.pt\/(?:[^/?#]+\/){1,2}fotos\/3\//i;


// ============================================================
// 2. FUNÇÕES AUXILIARES
// ============================================================

// Verifica se uma string contém texto.
const nonempty = value =>
  typeof value === 'string' &&
  value.trim().length > 0;

// Normaliza IDs do Notion para comparação.
const normalizeId = value =>
  String(value || '')
    .replace(/-/g, '')
    .toLowerCase();

// Interrompe a execução com uma mensagem identificável.
function bloquear(motivo) {
  throw new Error(`BLOQUEADO: ${motivo}`);
}


// ============================================================
// 3. VALIDAR DADOS DO ALOJAMENTO
// ============================================================

function validate(data, pageId) {

  // ----------------------------------------------------------
  // 3.1 Estado e identificação
  // ----------------------------------------------------------

  const estadosPermitidos = [
    'PARCIAL',
    'PENDENTE',
    'VALIDADO'
  ];

  if (
    !data ||
    !estadosPermitidos.includes(data.estado) ||
    normalizeId(data.pageId) !== normalizeId(pageId)
  ) {
    bloquear('estado ou pageId divergente.');
  }


  // ----------------------------------------------------------
  // 3.2 Estrutura obrigatória
  // ----------------------------------------------------------

  if (
    !nonempty(data.alojamento) ||
    !nonempty(data.urlAnuncio) ||
    !Number.isInteger(data.totalFotos) ||
    data.totalFotos < 1 ||
    !Array.isArray(data.fotos) ||
    !Array.isArray(data.pendentes)
  ) {
    bloquear('estrutura incompleta.');
  }


  // ----------------------------------------------------------
  // 3.3 Contagem e duplicações
  // ----------------------------------------------------------

  const todasFotos = [
    ...data.fotos,
    ...data.pendentes
  ];

  const numeros = todasFotos.map(foto => foto.numero);
  const urls = todasFotos.map(foto => foto.url);

  if (
    todasFotos.length !== data.totalFotos ||
    new Set(numeros).size !== data.totalFotos ||
    new Set(urls).size !== data.totalFotos
  ) {
    bloquear('contagem ou fotos duplicadas.');
  }


  // ----------------------------------------------------------
  // 3.4 Validar número e URL de cada fotografia
  // ----------------------------------------------------------

  for (const foto of todasFotos) {

    const numeroValido =
      Number.isInteger(foto.numero) &&
      foto.numero >= 1 &&
      foto.numero <= data.totalFotos;

    const urlValida =
      typeof foto.url === 'string' &&
      REGEX_FOTO.test(foto.url);

    if (!numeroValido || !urlValida) {
      bloquear('numero ou URL de foto invalido.');
    }
  }


  // ----------------------------------------------------------
  // 3.5 Validar fotografias já concluídas
  // ----------------------------------------------------------

  for (const foto of data.fotos) {

    const etiquetaValida =
      Number.isInteger(foto.etiqueta?.id) &&
      ETIQUETAS[foto.etiqueta?.nome] === foto.etiqueta?.id;

    if (
      foto.sucesso !== true ||
      !nonempty(foto.nome) ||
      foto.acessibilidade !== false ||
      !etiquetaValida
    ) {
      bloquear('foto concluida invalida.');
    }


    // --------------------------------------------------------
    // 3.6 Validar traduções PT / ES / EN / FR
    // --------------------------------------------------------

    for (const idioma of IDIOMAS) {

      for (const campo of ['title', 'descricao', 'alt']) {

        const valor = foto.traducoes?.[idioma]?.[campo];

        const valido =
          nonempty(valor) &&
          (campo !== 'title' || valor.length <= 70) &&
          (campo !== 'alt' || valor.length <= 125);

        if (!valido) {
          bloquear('traducao concluida incompleta.');
        }
      }
    }
  }


  // ----------------------------------------------------------
  // 3.7 Validar progresso registado
  // ----------------------------------------------------------

  if (
    data.fotosProcessadas !== undefined &&
    data.fotosProcessadas !== data.fotos.length
  ) {
    bloquear('fotosProcessadas inconsistente.');
  }

  if (
    data.estado === 'VALIDADO' &&
    data.pendentes.length > 0
  ) {
    bloquear('VALIDADO com pendentes.');
  }


  // ----------------------------------------------------------
  // 3.8 Confirmar próxima fotografia
  // ----------------------------------------------------------

  const proximaFoto = data.pendentes.length
    ? Math.min(...data.pendentes.map(foto => foto.numero))
    : null;

  if (
    data.proximaFoto !== undefined &&
    data.proximaFoto !== proximaFoto
  ) {
    bloquear('proximaFoto inconsistente.');
  }

  return data;
}


// ============================================================
// 4. CARREGAR E VALIDAR O PROGRESSO
// ============================================================

// Criar uma cópia independente dos dados recebidos.
const s = JSON.parse(
  JSON.stringify($input.first().json)
);

// Validar antes de continuar.
validate(s.data, s.pageId);


// ============================================================
// 5. SELECIONAR A PRÓXIMA FOTOGRAFIA
// ============================================================

// Ordenar por número crescente.
const fotosPendentes = [...s.data.pendentes].sort(
  (a, b) => a.numero - b.numero
);

// Selecionar apenas a primeira fotografia pendente.
s.current = fotosPendentes[0] || null;

// Não enviar pedidos sem fotografia.
if (!s.current) {
  bloquear('nenhuma fotografia pendente para analisar.');
}

// Guardar URL para o pedido Groq.
s.fotoUrl = s.current.url;


// ============================================================
// 6. PROMPT MULTILÍNGUE
// ============================================================

// O prompt é definido uma única vez e reutilizado na API.

s.prompt = `
Analisa exclusivamente a fotografia de um alojamento turístico.
Gera conteúdo comercial conciso, natural, profissional e factual.

Responde exclusivamente com um objeto JSON válido,
sem Markdown ou texto adicional, usando esta estrutura:

{
  "etiqueta": "Quarto",
  "traducoes": {
    "pt": {
      "title": "",
      "descricao": "",
      "alt": ""
    },
    "es": {
      "title": "",
      "descricao": "",
      "alt": ""
    },
    "en": {
      "title": "",
      "descricao": "",
      "alt": ""
    },
    "fr": {
      "title": "",
      "descricao": "",
      "alt": ""
    }
  }
}

ETIQUETA:

Escolhe exatamente uma destas opções:

${JSON.stringify(Object.keys(ETIQUETAS))}

Usa a etiqueta exatamente como escrita, sem a traduzir.
Escolhe a que melhor representa o elemento principal.
Se nenhuma for adequada, usa "Outros".

IDIOMAS E CAMPOS:

- pt: português europeu.
- es: espanhol de Espanha.
- en: inglês britânico.
- fr: francês natural.

- title:
  Título natural adequado a um anúncio turístico.
  Máximo de 70 caracteres.

- descricao:
  Uma única frase, idealmente com 10–25 palavras,
  acolhedora e profissional.
  Destaca uma experiência ou benefício sem repetir
  o título ou o alt.

- alt:
  Descrição objetiva e acessível dos elementos visíveis.
  Máximo de 125 caracteres.

REGRAS:

1. Mantém o mesmo significado factual nos quatro idiomas.

2. Preenche os 12 campos com strings não vazias.

3. Não inventes elementos, características ou comodidades
   não visíveis ou confirmados.

4. Não menciones cores em nenhum campo ou idioma.
   Evita nomes de cores e referências cromáticas
   como "claro", "escuro" ou "colorido".

5. Evita repetições, enumerações e exageros comerciais.

6. Baseia-te apenas nesta fotografia.
   Nunca reutilizes conteúdo de outras fotografias.

Devolve apenas o objeto JSON final.
`.trim();


// ============================================================
// 7. CONSTRUIR PEDIDO GROQ
// ============================================================

s.groqBody = {

  model: CONFIG_GROQ.model,

  messages: [
    {
      role: 'user',

      content: [
        {
          type: 'text',
          text: s.prompt
        },
        {
          type: 'image_url',
          image_url: {
            url: s.fotoUrl
          }
        }
      ]
    }
  ],

  response_format: {
    type: 'json_object'
  },

  temperature: CONFIG_GROQ.temperature,

  max_completion_tokens:
    CONFIG_GROQ.max_completion_tokens
};


// ============================================================
// 8. OUTPUT PARA O PRÓXIMO NÓ
// ============================================================

return [
  {
    json: s
  }
];

/**
 * ============================================================
 * MTPHOMES | INCORPORAR RESPOSTA GROQ
 * ============================================================
 *
 * Objetivo:
 *  1. Recuperar os dados do nó Preparar foto.
 *  2. Ler e validar a resposta do Groq.
 *  3. Incorporar a fotografia concluída.
 *  4. Atualizar o progresso do alojamento.
 *  5. Preservar o progresso em caso de erro.
