      bloquear('numero ou URL de foto invalido.');
    }
  }


  // ----------------------------------------------------------
  // 3.5 Validar fotografias concluídas
  // ----------------------------------------------------------

  for (const foto of data.fotos) {

    const etiquetaValida =
      Number.isInteger(foto.etiqueta?.id) &&
      ETIQUETAS[foto.etiqueta?.nome] === foto.etiqueta?.id;

    if (
      foto.sucesso !== true ||
      !nonempty(foto.nome) ||
      foto.acessibilidade !== false ||
      !etiquetaValida
    ) {
      bloquear('foto concluida invalida.');
    }


    // --------------------------------------------------------
    // 3.6 Validar traduções existentes
    // --------------------------------------------------------

    for (const idioma of IDIOMAS) {

      for (const campo of CAMPOS) {

        const valor = foto.traducoes?.[idioma]?.[campo];

        const valido =
          nonempty(valor) &&
          (
            campo !== 'title' ||
            valor.length <= LIMITES.title
          ) &&
          (
            campo !== 'alt' ||
            valor.length <= LIMITES.alt
          );

        if (!valido) {
          bloquear('traducao concluida incompleta.');
        }
      }
    }
  }


  // ----------------------------------------------------------
  // 3.7 Validar progresso
  // ----------------------------------------------------------

  if (
    data.fotosProcessadas !== undefined &&
    data.fotosProcessadas !== data.fotos.length
  ) {
    bloquear('fotosProcessadas inconsistente.');
  }

  if (
    data.estado === 'VALIDADO' &&
    data.pendentes.length > 0
  ) {
    bloquear('VALIDADO com pendentes.');
  }

  const proximaFoto = data.pendentes.length
    ? Math.min(...data.pendentes.map(foto => foto.numero))
    : null;

  if (
    data.proximaFoto !== undefined &&
    data.proximaFoto !== proximaFoto
  ) {
    bloquear('proximaFoto inconsistente.');
  }

  return data;
}


// ============================================================
// 4. LER E INTERPRETAR RESPOSTA GROQ
// ============================================================

function lerRespostaGroq(resposta) {

  // ----------------------------------------------------------
  // 4.1 Identificar erros da API
  // ----------------------------------------------------------

  if (resposta.error) {

    const erro = typeof resposta.error === 'string'
      ? resposta.error
      : JSON.stringify(resposta.error);

    throw new Error(erro);
  }


  // ----------------------------------------------------------
  // 4.2 Recuperar conteúdo gerado
  // ----------------------------------------------------------

  const raw = resposta.choices?.[0]?.message?.content;

  if (!nonempty(raw)) {
    throw new Error('Groq sem conteudo.');
  }


  // ----------------------------------------------------------
  // 4.3 Remover Markdown, caso exista
  // ----------------------------------------------------------

  const jsonLimpo = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');


  // ----------------------------------------------------------
  // 4.4 Interpretar JSON
  // ----------------------------------------------------------

  let resultado;

  try {
    resultado = JSON.parse(jsonLimpo);
  } catch {
    throw new Error('Groq devolveu JSON invalido.');
  }

  if (
    !resultado ||
    typeof resultado !== 'object' ||
    Array.isArray(resultado)
  ) {
    throw new Error('Estrutura da resposta Groq invalida.');
  }

  return resultado;
}


// ============================================================
// 5. VALIDAR ETIQUETA E TRADUÇÕES
// ============================================================

function validarRespostaIA(resultado) {

  // ----------------------------------------------------------
  // 5.1 Validar etiqueta
  // ----------------------------------------------------------

  const nomeEtiqueta = resultado.etiqueta;

  if (
    !Object.prototype.hasOwnProperty.call(
      ETIQUETAS,
      nomeEtiqueta
    )
  ) {
    throw new Error('Etiqueta invalida.');
  }


  // ----------------------------------------------------------
  // 5.2 Preparar traduções
  // ----------------------------------------------------------

  const traducoes = {};

  for (const idioma of IDIOMAS) {

    const original = resultado.traducoes?.[idioma] || {};

    // Aceitar nomes alternativos devolvidos pela IA.
    const valores = {
      title: original.title ?? original.titulo,

      descricao:
        original.descricao ??
        original.description ??
        original.descripcion,

      alt: original.alt
    };

    traducoes[idioma] = {};


    // --------------------------------------------------------
    // 5.3 Verificar os três campos
    // --------------------------------------------------------

    for (const campo of CAMPOS) {

      const valor = valores[campo];

      if (!nonempty(valor)) {
        throw new Error(
          `Campo invalido: ${idioma}.${campo}`
        );
      }

      const texto = valor.trim();

      if (
        campo === 'title' &&
        texto.length > LIMITES.title
      ) {
        throw new Error(
          `Titulo excede ${LIMITES.title} caracteres: ${idioma}`
        );
      }

      if (
        campo === 'alt' &&
        texto.length > LIMITES.alt
      ) {
        throw new Error(
          `ALT excede ${LIMITES.alt} caracteres: ${idioma}`
        );
      }

      traducoes[idioma][campo] = texto;
    }
  }

  return {
    nomeEtiqueta,
    traducoes
  };
}


// ============================================================
// 6. INCORPORAR FOTOGRAFIA CONCLUÍDA
// ============================================================

function incorporarFotografia(s, resultado) {

  const atual = s.current;

  // ----------------------------------------------------------
  // 6.1 Confirmar fotografia atual
  // ----------------------------------------------------------

  if (
    !atual ||
    !Number.isInteger(atual.numero) ||
    !nonempty(atual.url)
  ) {
    bloquear('fotografia atual invalida.');
  }

  // Verificar se ainda está na lista de pendentes.
  const existePendente = s.data.pendentes.some(
    foto =>
      foto.numero === atual.numero &&
      foto.url === atual.url
  );

  if (!existePendente) {
    bloquear('fotografia atual nao encontrada nos pendentes.');
  }

  // Impedir a incorporação da mesma fotografia duas vezes.
  const jaProcessada = s.data.fotos.some(
    foto =>
      foto.numero === atual.numero ||
      foto.url === atual.url
  );

  if (jaProcessada) {
    bloquear('fotografia ja processada.');
  }


  // ----------------------------------------------------------
  // 6.2 Construir objeto da fotografia
  // ----------------------------------------------------------

  const novaFoto = {
    numero: atual.numero,
    url: atual.url,

    nome: resultado.traducoes.pt.title,

    etiqueta: {
      nome: resultado.nomeEtiqueta,
      id: ETIQUETAS[resultado.nomeEtiqueta]
    },

    acessibilidade: false,

    traducoes: resultado.traducoes,

    sucesso: true
  };


  // ----------------------------------------------------------
  // 6.3 Guardar fotografia concluída
  // ----------------------------------------------------------

  s.data.fotos.push(novaFoto);

  // Manter ordem numérica.
  s.data.fotos.sort(
    (a, b) => a.numero - b.numero
  );


  // ----------------------------------------------------------
  // 6.4 Remover fotografia dos pendentes
  // ----------------------------------------------------------

  s.data.pendentes = s.data.pendentes.filter(
    foto => foto.numero !== atual.numero
  );

  return s;
}


// ============================================================
// 7. ATUALIZAR PROGRESSO DO ALOJAMENTO
// ============================================================

function atualizarProgresso(data) {

  // Quantidade de fotografias concluídas.
  data.fotosProcessadas = data.fotos.length;

  // Identificar a próxima fotografia.
  data.proximaFoto = data.pendentes.length
    ? Math.min(
        ...data.pendentes.map(foto => foto.numero)
      )
    : null;

  // Definir estado conforme as fotografias restantes.
  data.estado = data.pendentes.length
    ? 'PARCIAL'
    : 'VALIDADO';

  return data;
}


// ============================================================
// 8. RECUPERAR DADOS DOS NÓS ANTERIORES
// ============================================================

