  // 9.1 Ler resposta do Groq.
  const respostaIA = lerRespostaGroq(respostaGroq);

  // 9.2 Validar etiqueta e traduções.
  const resultado = validarRespostaIA(respostaIA);

  // 9.3 Incorporar fotografia ao JSON.
  incorporarFotografia(s, resultado);

  // 9.4 Marcar processamento bem-sucedido.
  s.stop = false;

