/**
 * ============================================================
 * MTPHOMES | PREPARAR PAYLOAD PARA NOTION
 * ============================================================
 *
 * Objetivo:
 *  1. Receber o JSON atualizado do alojamento.
 *  2. Validar a integridade das fotografias.
 *  3. Reconhecer URLs MTPHomes multilíngues.
 *  4. Simplificar o JSON quando estiver VALIDADO.
 *  5. Dividir o conteúdo para os blocos do Notion.
 *  6. Preparar o payload para atualização.
 *
 * Segurança:
 *  - Não permite fotografias duplicadas.
 *  - Não elimina progresso de alojamentos parciais.
 *  - Verifica etiquetas e traduções.
 *  - Confirma o progresso antes da gravação.
 *  - Respeita os limites dos rich_text do Notion.
 * ============================================================
 */


// ============================================================
// 1. CONFIGURAÇÕES
// ============================================================

const CONFIG = {
  idiomas: ['pt', 'es', 'en', 'fr'],

  estadosPermitidos: [
    'PARCIAL',
    'PENDENTE',
    'VALIDADO'
  ],

  limiteTitulo: 70,
  limiteAlt: 125,

  // Limite conservador por segmento rich_text.
  caracteresPorParte: 1900,

  // Máximo de segmentos num único bloco.
  maxPartes: 100
};


// ============================================================
// 2. ETIQUETAS AVANTIO
// ============================================================

const ETIQUETAS = {
  'Balcão': 14,
  'Cafeteria': 16,
  "Child's bedroom": 20,
  'Cozinha': 1,
  'Detalhes': 10,
  'Exterior': 9,
  'Fachada': 2,
  'Garagem': 8,
  'Jardim': 5,
  'Outros': 11,
  'Piscina': 6,
  'Plano': 18,
  'Quarto de banho': 4,
  'Quarto': 3,
  'Receção': 13,
  'Resort': 19,
  'Sala de estar': 12,
  'Sala de jantar': 15,
  'Terraço': 7,
  'Visualizações': 17
};


// ============================================================
// 3. VALIDAÇÃO DAS URLs
// ============================================================

/**
 * Aceita os caminhos multilíngues da MTPHomes:
 *
 * PT: /aluguer/fotos/3/...
 * EN: /en/rentals/fotos/3/...
 * ES: /es/.../fotos/3/...
 * FR: /fr/.../fotos/3/...
 *
 * Mantém a exigência do domínio oficial e HTTPS.
 */

const REGEX_FOTO =
  /^https:\/\/www\.mtphomes\.pt\/(?:[^/?#]+\/){1,2}fotos\/3\//i;


// ============================================================
// 4. FUNÇÕES AUXILIARES
// ============================================================

// Verificar se uma string contém texto.
function nonempty(value) {
  return (
    typeof value === 'string' &&
    value.trim().length > 0
  );
}

// Normalizar IDs do Notion para comparação.
function normalizeId(value) {
  return String(value || '')
    .replace(/-/g, '')
    .toLowerCase();
}

// Interromper execução quando uma validação falhar.
function bloquear(motivo) {
  throw new Error(`BLOQUEADO: ${motivo}`);
}


// ============================================================
// 5. VALIDAR ESTRUTURA DO ALOJAMENTO
// ============================================================

function validate(data, pageId) {

  // ----------------------------------------------------------
  // 5.1 Estado e identificação
  // ----------------------------------------------------------

  if (
    !data ||
    !CONFIG.estadosPermitidos.includes(data.estado) ||
    normalizeId(data.pageId) !== normalizeId(pageId)
  ) {
    bloquear('estado ou pageId divergente.');
  }


  // ----------------------------------------------------------
  // 5.2 Estrutura obrigatória
  // ----------------------------------------------------------

  if (
    !nonempty(data.alojamento) ||
    !nonempty(data.urlAnuncio) ||
    !Number.isInteger(data.totalFotos) ||
    data.totalFotos < 1 ||
    !Array.isArray(data.fotos) ||
    !Array.isArray(data.pendentes)
  ) {
    bloquear('estrutura incompleta.');
  }


  // ----------------------------------------------------------
  // 5.3 Contagem e duplicações
  // ----------------------------------------------------------

  const todasFotos = [
    ...data.fotos,
    ...data.pendentes
  ];

  const numeros = todasFotos.map(
    foto => foto?.numero
  );

  const urls = todasFotos.map(
    foto => foto?.url
  );

  if (
    todasFotos.length !== data.totalFotos ||
    new Set(numeros).size !== data.totalFotos ||
    new Set(urls).size !== data.totalFotos
  ) {
    bloquear('contagem ou fotos duplicadas.');
  }


  // ----------------------------------------------------------
  // 5.4 Validar números e URLs das fotografias
  // ----------------------------------------------------------

  for (const foto of todasFotos) {

    const numeroValido =
      Number.isInteger(foto?.numero) &&
      foto.numero >= 1 &&
      foto.numero <= data.totalFotos;

    const urlValida =
      typeof foto?.url === 'string' &&
      REGEX_FOTO.test(foto.url);

    if (!numeroValido || !urlValida) {
      bloquear(
        'numero ou URL de foto invalido' +
        ` (foto ${foto?.numero ?? 'desconhecida'}).`
      );
    }
  }


  // ----------------------------------------------------------
  // 5.5 Validar fotografias concluídas
  // ----------------------------------------------------------

  for (const foto of data.fotos) {

    const etiquetaValida =
      Number.isInteger(foto.etiqueta?.id) &&
      ETIQUETAS[foto.etiqueta?.nome] ===
        foto.etiqueta?.id;

    if (
      foto.sucesso !== true ||
      !nonempty(foto.nome) ||
      foto.acessibilidade !== false ||
      !etiquetaValida
    ) {
      bloquear(
        `foto concluida invalida: ${foto.numero}.`
      );
    }


    // --------------------------------------------------------
    // 5.6 Validar traduções PT / ES / EN / FR
    // --------------------------------------------------------

    for (const idioma of CONFIG.idiomas) {

      for (const campo of [
        'title',
        'descricao',
        'alt'
      ]) {

        const valor =
          foto.traducoes?.[idioma]?.[campo];

        const valido =
          nonempty(valor) &&
          (
            campo !== 'title' ||
            valor.length <= CONFIG.limiteTitulo
          ) &&
          (
            campo !== 'alt' ||
            valor.length <= CONFIG.limiteAlt
          );

        if (!valido) {
          bloquear(
            `traducao invalida: foto ${foto.numero}, ` +
            `${idioma}.${campo}.`
          );
        }
      }
    }
  }


  // ----------------------------------------------------------
  // 5.7 Validar quantidade processada
  // ----------------------------------------------------------

  if (
    data.fotosProcessadas !== undefined &&
    data.fotosProcessadas !== data.fotos.length
  ) {
    bloquear('fotosProcessadas inconsistente.');
  }


  // ----------------------------------------------------------
  // 5.8 Verificar estado VALIDADO
  // ----------------------------------------------------------

  if (
    data.estado === 'VALIDADO' &&
    data.pendentes.length > 0
  ) {
    bloquear('VALIDADO com pendentes.');
  }


  // ----------------------------------------------------------
  // 5.9 Verificar próxima fotografia
  // ----------------------------------------------------------

  const proximaFoto = data.pendentes.length
    ? Math.min(
        ...data.pendentes.map(foto => foto.numero)
      )
    : null;

  if (
    data.proximaFoto !== undefined &&
    data.proximaFoto !== proximaFoto
  ) {
    bloquear('proximaFoto inconsistente.');
  }

  return data;
}


// ============================================================
// 6. PREPARAR JSON FINAL
// ============================================================

function prepararJsonFinal(data) {

  // ----------------------------------------------------------
  // 6.1 Alojamento ainda possui fotografias pendentes
  // ----------------------------------------------------------

  if (data.pendentes.length > 0) {

    // Preservar todos os dados:
    // - fotos concluídas
    // - fotos pendentes
    // - estado
    // - progresso
    // - erro de execução, caso exista

    return data;
  }


  // ----------------------------------------------------------
  // 6.2 Todas as fotografias foram concluídas
  // ----------------------------------------------------------

  // Gerar JSON simplificado para o estado VALIDADO.
  // Mantém o formato utilizado pelo workflow original.

  return {
    estado: 'VALIDADO',

    alojamento: data.alojamento,

    pageId: data.pageId,

    urlAnuncio: data.urlAnuncio,

    totalFotos: data.totalFotos,

    fotos: data.fotos
  };
}


// ============================================================
// 7. DIVIDIR JSON PARA O NOTION
// ============================================================

function dividirTexto(texto) {

  const partes = [];

  let parteAtual = '';

  for (const caractere of texto) {

    // Usar o comprimento real do caractere em JavaScript.
    // Isto evita ultrapassar o limite por causa de emojis
    // ou outros caracteres Unicode.

    if (
      parteAtual.length + caractere.length >
      CONFIG.caracteresPorParte
    ) {

      partes.push(parteAtual);
      parteAtual = '';
    }

    parteAtual += caractere;
  }

  if (parteAtual.length > 0) {
    partes.push(parteAtual);
  }

  if (partes.length > CONFIG.maxPartes) {
    bloquear(
      'JSON excede capacidade do bloco Notion.'
    );
  }

  return partes;
}


// ============================================================
// 8. CONSTRUIR PAYLOAD NOTION
// ============================================================

function construirPayload(data) {

  // Converter o alojamento para JSON formatado.
  const texto = JSON.stringify(data, null, 2);

  // Dividir em segmentos compatíveis com o Notion.
  const partes = dividirTexto(texto);

  // Construir a estrutura do bloco de código.
  return {
    code: {
      language: 'json',

      rich_text: partes.map(content => ({
        type: 'text',

        text: {
          content
        }
      }))
    }
  };
}


// ============================================================
// 9. RECEBER DADOS DO NÓ ANTERIOR
// ============================================================

// Criar cópia independente dos dados recebidos.
const s = JSON.parse(
  JSON.stringify($input.first().json)
);


// ============================================================
// 10. VALIDAR ANTES DE PREPARAR O PAYLOAD
// ============================================================

// Não permitir gravação de dados inconsistentes.
validate(s.data, s.pageId);


// ============================================================
// 11. PREPARAR E INCORPORAR O PAYLOAD
// ============================================================

// Gerar JSON final.
// PARCIAL: preservar progresso completo.
// VALIDADO: utilizar estrutura simplificada.
s.data = prepararJsonFinal(s.data);

// Construir payload para atualização do bloco Notion.
s.payload = construirPayload(s.data);


// ============================================================
// 12. OUTPUT PARA O PRÓXIMO NÓ
// ============================================================

return [
  {
    json: s
  }
];

